function plot_results()
%PLOT_RESULTS OPTIONAL starter for Member 3: plot only, NO model equations.
% Reads the exact CSV outputs generated by main.m and writes four PNGs.
    root = fileparts(fileparts(mfilename('fullpath')));
    csv_dir = fullfile(root, 'results', 'csv');
    fig_dir = fullfile(root, 'results', 'figures');
    if ~exist(fig_dir, 'dir'), mkdir(fig_dir); end
    D = readtable(fullfile(csv_dir, 'distance.csv'));
    A = readtable(fullfile(csv_dir, 'altitude.csv'));
    E = readtable(fullfile(csv_dir, 'environment.csv'));

    fig = figure('Visible','off');
    plot(D.r_m, D.fspl_dB, 'LineWidth',1.6); hold on;
    plot(D.r_m, D.pl_avg_dB, 'LineWidth',1.6);
    grid on; xlabel('Horizontal distance r (m)'); ylabel('Path loss (dB)');
    title('Distance sweep: FSPL versus mean A2G path loss');
    legend('FSPL','Mean A2G path loss','Location','best');
    saveas(fig, fullfile(fig_dir, 'pathloss_vs_distance.png')); close(fig);

    fig = figure('Visible','off');
    plot(A.h_m, A.p_los, 'LineWidth',1.6);
    grid on; ylim([0 1]);
    xlabel('UAV altitude h (m)'); ylabel('LoS probability');
    title('LoS probability versus UAV altitude');
    saveas(fig, fullfile(fig_dir, 'los_vs_altitude.png')); close(fig);

    fig = figure('Visible','off');
    plot(A.h_m, A.pl_avg_dB, 'LineWidth',1.6);
    grid on; xlabel('UAV altitude h (m)'); ylabel('Mean path loss (dB)');
    title('Mean A2G path loss versus UAV altitude');
    saveas(fig, fullfile(fig_dir, 'pathloss_vs_altitude.png')); close(fig);

    fig = figure('Visible','off'); hold on;
    env_names = unique(E.environment, 'stable');
    for k = 1:numel(env_names)
        if iscell(env_names)
            name = env_names{k};
        else
            name = char(env_names(k));
        end
        rows = strcmp(E.environment, name);
        plot(E.r_m(rows), E.pl_avg_dB(rows), 'LineWidth', 1.6, ...
            'DisplayName', name);
    end
    grid on; xlabel('Horizontal distance r (m)');
    ylabel('Mean path loss (dB)');
    title('A2G channel: environment comparison');
    legend('show','Location','best');
    saveas(fig, fullfile(fig_dir, 'environment_comparison.png')); close(fig);
    fprintf('Generated 4 figures in %s\n', fig_dir);
end
